import React from 'react';

const NewsCard = ({ article }) => (
  <div className="news-card">
    <img src={article.imageUrl} alt={article.title} />
    <h3>{article.title}</h3>
    <p>{article.description}</p>
  </div>
);

export default NewsCard;
